package com.bank.statement;

import java.math.BigDecimal;
import java.util.List;
import java.util.Locale;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class StatementFormatDemo {
    private static final Logger log = Logger.getLogger(StatementFormatDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "rajesh kumar", new BigDecimal("1000000.00"));
        StatementFormatService svc = new StatementFormatService();

        // Non-mutating proof: original name is unchanged after toUpperCase.
        String name = rajesh.getHolderName();
        String upper = name.toUpperCase(Locale.ROOT);
        log.info(() -> "original name still = '" + name + "', new upper = '" + upper + "'");

        // Masking with substring + charAt.
        String masked = svc.maskAccount(rajesh.getAccountId());
        log.info(() -> "masked account = " + masked);

        // Clean a grouped amount string with literal replace (NOT replaceAll).
        String cleaned = svc.cleanAmount("10,00,000.00");
        log.info(() -> "cleaned amount = " + cleaned);

        // Split a CSV line KEEPING trailing empty fields.
        List<String> fields = svc.parseCsv("TXN-1,SAV2001,45000.00,,");
        log.info(() -> "csv fields (" + fields.size() + ") = " + fields);

        // Format a currency statement line and join a record.
        String line = svc.formatLine(upper, rajesh.getAccountId(), rajesh.getBalance());
        log.info(() -> "statement line = " + line);
    }
}

