class Account {
    private final String accountId;
    private final String holderName;
    private BigDecimal balance;

    Account(String accountId, String holderName, BigDecimal balance) {
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
    }
    String getAccountId() { return accountId; }
    String getHolderName() { return holderName; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal amt) { this.balance = this.balance.subtract(amt); }
    void credit(BigDecimal amt) { this.balance = this.balance.add(amt); }
}

// ─── Would be in service/StatementFormatService.java in a real project ───
class StatementFormatService {
    private static final Logger log = Logger.getLogger(StatementFormatService.class.getName());

    // charAt + substring to mask all but the last 4 characters.
    String maskAccount(String accountId) {
        int visible = 4;
        if (accountId.length() <= visible) return accountId;
        String suffix = accountId.substring(accountId.length() - visible); // slice
        StringBuilder masked = new StringBuilder();
        for (int i = 0; i < accountId.length() - visible; i++) {
            masked.append('X');          // charAt not needed; length drives mask
        }
        return masked.append(suffix).toString();
    }

    // Literal replace of grouping commas (NOT a regex).
    String cleanAmount(String grouped) {
        String noCommas = grouped.replace(",", "");  // literal, safe
        if (!noCommas.strip().startsWith("-") && noCommas.contains("..")) {
            log.warning("Suspicious amount format");
        }
        return noCommas;
    }

    // split with limit -1 keeps trailing empty fields.
    List<String> parseCsv(String line) {
        String[] parts = line.split(",", -1);   // keep trailing empties
        return List.of(parts);
    }

    // String.format for currency + String.join to build a record.
    String formatLine(String name, String accountId, BigDecimal balance) {
        String amount = String.format(Locale.ROOT, "Rs.%,.2f", balance);
        return String.join(" | ", name, maskAccount(accountId), amount);
    }
}

// ─── Would be in util/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override
    public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
